mapper.select:
SELECT client_id, public_ip, get_url_host_v1(url) AS host, start_time, duration_ms FROM web_visit_record
AND to_timestamp(start_time / 1000)::date = #{query.visitDate}
AND client_id = #{query.clientId}

SELECT t.client_id, t.host, t.visit_day, SUM(t.duration_ms) AS total_duration_ms, SUM(t.duration_ms) / 1000 AS total_duration_sec FROM ( SELECT client_id, get_url_host_v1(url) AS host, to_timestamp(start_time / 1000)::date AS visit_day, duration_ms FROM web_visit_record
AND to_timestamp(start_time / 1000)::date = #{query.visitDate}
AND client_id = #{query.clientId}
) t GROUP BY t.client_id, t.host, t.visit_day ORDER BY total_duration_ms DESC
